-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "zhTW" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.mage.fire.Name"] = "火焰"
L["rm.era.mage.fire.Description"] = "火焰，適用於 10 至 60 級，在你有火焰天賦點數且沒有冰霜點數，或火焰是你的主要天賦樹時選用。以炎爆術開場（否則用火球術）；氣定神閒後使用炎爆術；擁有強化灼燒時，以灼燒對會存活較久的目標維持五層火焰易傷；以火焰衝擊與灼燒收尾；火球術作為填充。三個以上敵人交戰時：衝擊波、烈焰風暴、魔爆術、冰錐術、暴風雪。提醒：對精英與長時間戰鬥在灼燒疊滿五層時使用燃燒、護甲、秘法智慧、法力寶石、寒冰護體、法力護盾、喚醒、法術反制、解除次級詛咒、寒冰屏障、氣定神閒。預設關閉：火焰衝擊一就緒就穿插施放。"
L["rm.era.mage.fire.warcrafttavern.Name"] = "火焰（Warcraft Tavern）"
L["rm.era.mage.fire.warcrafttavern.Description"] = "依據 Warcraft Tavern 的火焰，作為推薦的火焰內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。對精英與首領在拉怪時就使用燃燒，而不是等待灼燒疊層；以炎爆術開場；擁有強化灼燒時以灼燒維持五層；火球術作為填充；火焰衝擊只在移動時使用。怪群時：先烈焰風暴，然後近距離時使用魔爆術、冰錐術與衝擊波，遠距離時使用暴風雪。提醒與火焰內建循環相同。"
L["rm.era.mage.frost.Name"] = "冰霜"
L["rm.era.mage.frost.Description"] = "冰霜，適用於 1 至 60 級，也適用於秘法天賦配置，並且是法師在取得天賦前的預設循環。寒冰箭（4 級前為火球術）；怪物接近你時使用冰霜新星，團隊首領除外；若你有強化秘法飛彈，怪物接近你後使用秘法飛彈；三個以上敵人交戰時使用冰錐術、魔爆術與暴風雪；移動時若法力有餘則使用火焰衝擊；單人時以火焰衝擊與魔杖收掉普通怪物；法力耗盡時使用魔杖。提醒：護甲（單人時冰甲術，隊伍中魔甲術，絕不替換你自己選的護甲）、秘法智慧、製造與使用法力寶石、寒冰護體、法力護盾、喚醒、法術反制、解除次級詛咒、寒冰屏障、急速冷卻、秘法強化與氣定神閒。預設關閉：搭配碎冰的烈焰風暴，以及用等級 1 的寒冰箭疊加深冬之寒。閃現術、變形術、放風箏與目標選擇由你自行處理。"
L["rm.era.mage.frost.icyveins.Name"] = "冰霜群體練功（Icy Veins）"
L["rm.era.mage.frost.icyveins.Description"] = "依據 Icy Veins 群體練功指南的暴風雪升級法，在你單人遊玩且擁有強化暴風雪時自動選用。兩個以上敵人交戰時：對怪群使用冰霜新星，冰霜新星冷卻時使用冰錐術，身邊沒有敵人時使用暴風雪，有敵人在身邊時使用魔爆術；單一目標使用寒冰箭，以火焰衝擊與魔杖收尾。每次拉怪前施放法力護盾與寒冰護體。聚集怪群、閃現術與放風箏由你自行處理。"
L["rm.forever.mage.arcane.Name"] = "秘法"
L["rm.forever.mage.arcane.Description"] = "當秘法是你的主要天賦樹且已投入 11 點，並學會秘法衝擊後的秘法。單人時以寒冰箭拉怪，隊伍中以秘法衝擊拉怪；接著飛彈彈幕觸發時使用秘法飛彈，節能施法時使用秘法衝擊，秘法衝擊疊滿三層時使用秘法懲戒，在負擔得起時（永久版本會隱藏法力）對精英疊加秘法衝擊至四層、對其他目標疊加至兩層，然後以霜火箭、寒冰箭或火球術來觸發飛彈彈幕，單人且無法負擔法術時使用魔杖。沒有秘法懲戒時（較早的測試版設計）由火焰衝擊消耗層數。移動時：火焰衝擊。三個以上敵人與你交戰時：魔爆術。提醒：對精英使用氣定神閒與秘法強化（秘法強化不再等到法力剩一半），以及法師的常規維持提醒。"
L["rm.forever.mage.fire.Name"] = "火焰"
L["rm.forever.mage.fire.Description"] = "當火焰是你的主要天賦樹且已投入 11 點（炎爆術所在層）後的火焰。對精英以炎爆術拉怪，否則用霜火箭或火球術；接著在升溫疊滿三層時使用炎爆術，冰霜之指觸發或目標被冰凍時使用冰霜長矛（火焰/冰霜混合流派），火焰衝擊冷卻結束即使用，對精英使用灼燒維持五層火焰易傷，霜火箭（40 級起）或火球術，單人且無法負擔法術時使用魔杖。移動時：火焰衝擊或冰霜長矛。四個以上敵人與你交戰時：烈焰風暴、衝擊波、魔爆術。灼燒只有在你擁有強化灼燒時才會開始疊層；近距離灼燒在你啟用之前維持關閉。提醒：對精英使用燃燒與氣定神閒，以及法師的常規維持提醒。"
L["rm.forever.mage.fire.icyveins.Name"] = "火焰升級（Icy Veins）"
L["rm.forever.mage.fire.icyveins.Description"] = "Icy Veins 不點強化灼燒的火焰升級天賦配置，作為推薦的火焰內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。以炎爆術拉怪，以火焰衝擊消耗火焰甦醒，怪物靠近時使用灼燒（永久版本會隱藏目標生命力，因此收掉低血量目標由你自行處理），然後是霜火箭（40 級起）或火球術。範圍傷害、移動、魔杖與提醒都與火焰內建循環相同，但不含燃燒與氣定神閒。"
L["rm.forever.mage.frost.Name"] = "冰霜"
L["rm.forever.mage.frost.Description"] = "冰霜，適用於 1 至 60 級，也是永久法師在學會天賦法術前的預設循環（4 級學會寒冰箭之前為火球術）。以寒冰箭拉怪；接著在冰霜之指觸發或目標被冰凍時使用冰霜長矛（寒冰箭仍在施放時也可使用，以取消或合併施法），深冬之寒疊滿五層時使用冰錐術，飛彈彈幕觸發時使用秘法飛彈，然後是寒冰箭，單人且無法負擔寒冰箭時使用魔杖。移動時：冰霜長矛，否則火焰衝擊。三個以上敵人與你交戰時：冰錐術；五個以上時：暴風雪，或在有怪物貼身時使用魔爆術。包含 Warcraft Tavern 的烈焰風暴與魔爆術範圍傷害打法，但預設關閉。提醒：秘法智慧、護甲（單人用冰甲術或霜甲術，隊伍中用魔甲術，絕不取代你已選擇的護甲）、寒冰護體、法術反制、解除次級詛咒、怪物貼身時的冰霜新星、急速冷卻。在永久版本中，插件看不到生命力與法力，因此用火焰衝擊收掉低血量目標、喚醒與寒冰屏障都由你決定；閃現術、放風箏、變形術與法力寶石也由你自行處理。"
L["rm.mop.mage.arcane.Name"] = "推薦"
L["rm.mop.mage.arcane.Description"] = "推薦秘法使用，適用於 10 至 90 級（在秘法專精下選用）。以秘法衝擊累積四層秘法充能；四層時若有秘法飛彈!觸發就用秘法飛彈消耗，沒有觸發時則在法力降到 90% 以下後使用秘法彈幕。法力高於 95% 時會持續施放秘法衝擊，這也是模擬器的打法。秘法飛彈絕不會留著兩層觸發不用，時光倒轉回溯前會施放秘法彈幕，兩個以上敵人時每四層充能就施放秘法彈幕；五個敵人在近處時使用冰錐術與魔爆術。維持你的天賦炸彈，移動且沒有浮冰時使用火焰衝擊或冰霜長矛。提醒：四層充能且有觸發時使用秘法強化與時光倒轉、霜甲術（54 級前為炎甲術）、秘法光輝、法術反制、法力寶石、鏡像、寒冰護體、浮冰、力之符文或祈願。時間扭曲、法術竊取與氣定神閒預設關閉；力之符文仍需手動擺放。"
L["rm.mop.mage.arcane.icyveins.Name"] = "四層充能時使用秘法彈幕（Icy Veins）"
L["rm.mop.mage.arcane.icyveins.Description"] = "指南的秘法規則（Icy Veins、Wowhead、Method、wowtbc.gg），推薦秘法內建循環的替代方案：四層秘法充能時，若有觸發就使用秘法飛彈，否則不論法力多少都使用秘法彈幕；秘法飛彈只在四層充能時使用。其餘一切（時光倒轉、炸彈、範圍傷害、移動、提醒）與推薦的循環相同，只是秘法強化會在四層充能時建議，不等待觸發。預設關閉：啟用它並停用推薦的秘法內建循環，或提高它的優先順序。"
L["rm.mop.mage.fire.Name"] = "推薦"
L["rm.mop.mage.fire.Description"] = "推薦火焰使用，適用於 10 至 90 級（在火焰專精下選用）。以讀條炎爆術開場，接著以煉獄衝擊（24 級前為火焰衝擊）將升溫轉為炎爆術!觸發，並立即施放，除非燃火即將冷卻結束；然後在你施放火球術時等待下一次升溫。燃火會在炎爆術之後立即施放，此時目標身上有點燃與炎爆術的燃燒效果；插件無法看到點燃有多大，因此較弱的點燃請自行判斷。維持你的天賦炸彈，兩個以上敵人與你交戰時以煉獄衝擊擴散，附近有五個敵人時使用冰錐術與魔爆術，移動時使用灼燒。提醒：炎甲術、氣定神閒、兩種觸發都有時使用時光倒轉、法力寶石、秘法光輝、法術反制、鏡像、寒冰護體、浮冰、祈願或力之符文。龍之吐息、時間扭曲與法術竊取預設關閉。"
L["rm.mop.mage.fire.icyveins.Name"] = "保留炎爆術!（Icy Veins）"
L["rm.mop.mage.fire.icyveins.Description"] = "Icy Veins、Method 與 wowtbc.gg 的火焰打法，推薦火焰內建循環的替代方案：炎爆術!觸發會保留到升溫也出現，再與你的火球術一起施放，只有在即將過期時才單獨消耗。其餘與推薦的循環相同。預設關閉：啟用它並停用推薦的火焰內建循環，或提高它的優先順序。"
L["rm.mop.mage.frost.Name"] = "推薦"
L["rm.mop.mage.frost.Description"] = "10 至 90 級的冰霜（在冰霜專精下選用）。兩層冰霜之指時使用冰霜長矛，腦部凍結觸發時使用霜火箭，你的天賦炸彈，冰霜之球，一層冰霜之指時使用冰霜長矛，寒冰箭；87 級起，若時光倒轉再不到 10 秒就就緒，會保留觸發給它。兩個以上敵人時：冰霜之球，敵人在近處時使用冰錐術與魔爆術，四個敵人站著不動時使用暴風雪。移動且沒有浮冰時使用冰霜長矛與火焰衝擊。提醒：水元素、對首領以外的目標使用冰凍術（請自行擺放）、配合時光倒轉使用冰寒脈動、冰寒脈動期間兩層冰霜之指時使用時光倒轉、霜甲術（54 級前為炎甲術）、法力寶石、秘法光輝、法術反制、鏡像、寒冰護體、浮冰、祈願或力之符文。急速冷卻、氣定神閒、時間扭曲與法術竊取預設關閉。"
L["rm.mop.mage.unspecialized.Name"] = "選擇專精前"
L["rm.mop.mage.unspecialized.Description"] = "適用於 1 至 9 級，以及尚未選擇專精的任何法師。霜火箭，以火焰衝擊收尾或在移動時使用，學會後在移動時使用冰霜長矛，三個以上敵人在近戰範圍內時使用魔爆術。提醒：怪物接近你時使用冰霜新星、法術反制，以及學會後的炎甲術與秘法光輝。10 級選擇專精後會切換為該專精的內建循環。"
L["rm.retail.mage.arcane.Name"] = "暴雪戰鬥助手"
L["rm.retail.mage.arcane.Description"] = "推薦秘法專精使用。醒目提示暴雪戰鬥助手建議的下一個法術，這是在至暗之夜的戰鬥中，遊戲仍允許插件讀取的唯一循環建議；你施法或引導時它會等待。同時提醒戰鬥助手留給你處理的部分：戰鬥中的秘法奔騰、脫戰時的秘法智力、對可中斷的施法使用法術反制、戰鬥中只要就緒就使用稜彩屏障，以及戰鬥中你的種族冷卻技能。敵人的施法在戰鬥中會被隱藏，因此法術反制只會在遊戲顯示它們的場合亮起；正式版中生命力是隱藏的，因此寒冰屏障與其他緊急技能由你決定。鏡像、時光倒轉、閃現術與飾品由你自行處理。"
L["rm.retail.mage.arcane.guide.Name"] = "參考（Icy Veins 與 SimulationCraft）"
L["rm.retail.mage.arcane.guide.Description"] = "僅供參考，預設關閉：指南中的秘法優先順序。在至暗之夜的戰鬥中，秘法齊射與節能施法對插件隱藏（只有秘法充能仍然可見），因此它無法在戰鬥中運作；正式版中法力是隱藏的，因此法力偏低時的喚醒由你決定；可以閱讀它，或複製後自行實驗。以秘法衝擊拉怪。日怒：秘法齊射低於 12 層且節能施法觸發時使用秘法飛彈，秘法靈魂以外使用稜光箭，四層秘法充能且秘法齊射達到 12 層並有節能施法或秘法齊射達到 25 層時，或秘法靈魂期間不論充能層數，使用秘法彈幕，稜光箭，秘法充能少於三層時使用秘法光球，面對三個敵人或沒有秘法充能時使用秘法脈衝，秘法衝擊。拋法者（已學會分裂魔法）：稜光箭，面對成群敵人時使用秘法光球，秘法齊射達到 20 層時使用秘法彈幕（面對兩個以上敵人時只在四層秘法充能時使用），秘法齊射低於 15 層且節能施法觸發時使用秘法飛彈，秘法充能少於三層時使用秘法光球與秘法脈衝（秘法奔騰期間不用秘法脈衝），秘法衝擊。無法施放秘法衝擊時使用秘法彈幕。提醒：秘法奔騰、在秘法奔騰期間或離秘法奔騰還久時，於秘法彈幕或稜光箭之後使用魔導師之觸、沒有秘法充能時在秘法彈幕之後使用氣定神閒，以及戰鬥助手內建循環中的提醒。"
L["rm.retail.mage.fire.Name"] = "暴雪戰鬥助手"
L["rm.retail.mage.fire.Description"] = "推薦火焰專精使用。醒目提示暴雪戰鬥助手建議的下一個法術，這是在至暗之夜的戰鬥中，遊戲仍允許插件讀取的唯一循環建議；你施法或引導時它會等待。同時提醒戰鬥助手留給你處理的部分：戰鬥中的燃灼、脫戰時的秘法智力、對可中斷的施法使用法術反制、戰鬥中只要就緒就使用熾炎屏障，以及戰鬥中你的種族冷卻技能。敵人的施法在戰鬥中會被隱藏，因此法術反制只會在遊戲顯示它們的場合亮起；正式版中生命力是隱藏的，因此寒冰屏障與其他緊急技能由你決定。"
L["rm.retail.mage.fire.guide.Name"] = "參考（Icy Veins、Wowhead 與 SimulationCraft）"
L["rm.retail.mage.fire.guide.Description"] = "僅供參考，預設關閉：指南中的火焰優先順序。焦炎之痕、升溫、終極炎爆術與火焰衝擊的充能在至暗之夜的戰鬥中會被隱藏，因此它無法在戰鬥中運作。在施法即將完成時使用火焰衝擊，把升溫轉為焦炎之痕；以炎爆術拉怪。高熱觸發時使用炎爆術（四個以上敵人時改用烈焰風暴），隕石，焦炎之痕觸發時使用炎爆術，燃灼期間升溫觸發時使用火焰衝擊，終極炎爆術觸發時使用炎爆術，搖曳火光觸發或移動中使用灼燒，升溫觸發時使用火焰衝擊，然後是霜火箭或火球術。提醒：詠唱法術即將完成時使用燃灼、熾炎屏障以及功能性提醒。等待縱火狂階段結束，以及讓隕石落在燃灼期間的時機由你自行處理。"
L["rm.retail.mage.frost.Name"] = "暴雪戰鬥助手"
L["rm.retail.mage.frost.Description"] = "推薦冰霜專精使用。醒目提示暴雪戰鬥助手建議的下一個法術，這是在至暗之夜的戰鬥中，遊戲仍允許插件讀取的唯一循環建議；你施法或引導時它會等待。同時提醒戰鬥助手留給你處理的部分：已學會天賦但沒有水元素時使用召喚水元素、脫戰時的秘法智力、對可中斷的施法使用法術反制、戰鬥中只要就緒就使用寒冰護體，以及戰鬥中你的種族冷卻技能。敵人的施法在戰鬥中會被隱藏，因此法術反制只會在遊戲顯示它們的場合亮起；正式版中生命力是隱藏的，因此寒冰屏障與其他緊急技能由你決定。"
L["rm.retail.mage.frost.guide.Name"] = "參考（Icy Veins 與 SimulationCraft）"
L["rm.retail.mage.frost.guide.Description"] = "僅供參考，預設關閉：指南中針對各英雄天賦的冰霜優先順序。觸發效果、凍結層數與冷卻在至暗之夜的戰鬥中會被隱藏，因此它無法在戰鬥中運作。以霜火箭或寒冰箭拉怪。霜火（已學會霜火箭）：冰川長槍就緒即用，一到兩個敵人時使用彗星風暴，腦部凍結觸發且沒有熱能虛空時使用冰雪紛飛，兩層冰霜之指時使用冰霜長矛，冰霜射線，冰霜之球，三個敵人且凍結之雨觸發時使用暴風雪，有熱能虛空時冰霜之指觸發或凍結達到十二層時使用冰霜長矛，冰雪紛飛，五個敵人時使用寒冰新星或冰錐術，然後是冰川長槍或霜火箭。拋法者：彗星風暴，腦部凍結觸發時使用冰雪紛飛，兩層冰霜之指時使用冰霜長矛，冰霜之球，冰川長槍就緒即用，凍結之雨觸發時使用暴風雪，冰霜之指觸發或凍結達到六層時使用冰霜長矛，冰霜射線，冰雪紛飛，四個敵人時使用寒冰新星或冰錐術，七個敵人時使用暴風雪，然後是冰川長槍或寒冰箭。移動中使用冰霜長矛。提醒：召喚水元素、寒冰護體以及功能性提醒。"
L["rm.retail.mage.initial.Name"] = "暴雪戰鬥助手"
L["rm.retail.mage.initial.Description"] = "在你選擇專精之前推薦使用（此時遊戲回報的是法師的初始專精）。醒目提示暴雪戰鬥助手建議的下一個法術，這是在至暗之夜的戰鬥中，遊戲仍允許插件讀取的唯一循環建議；你施法或引導時它會等待。同時附上每個法師內建循環共用的提醒，各項在你學會對應法術後才會出現。當你在 10 級選擇專精後，該專精的內建循環會接手。"
L["rm.sod.mage.arcane.Name"] = "秘法（探索賽季）"
L["rm.sod.mage.arcane.Description"] = "探索賽季的秘法傷害，秘法是你的主要天賦樹且已紋刻秘法衝擊時選用。飛彈彈幕觸發時使用秘法飛彈；四層秘法衝擊時使用秘法彈幕；安全時使用野火箭，但野火箭已疊到四層以上時絕不使用；活化烈焰冷卻結束即使用；秘法衝擊作為填充。移動時使用秘法彈幕與火焰衝擊；怪群時使用活化烈焰與魔爆術。提醒：對精英與長時間戰鬥使用秘法強化、搭配秘法強化或移動時使用氣定神閒、冰寒脈動、急速冷卻以及其他法師提醒。"
L["rm.sod.mage.fire.Name"] = "火焰（探索賽季）"
L["rm.sod.mage.fire.Description"] = "探索賽季的火焰，適用於 1 至 60 級，也是探索賽季中法師的預設循環。使用你已紋刻的符文：焦炎之痕觸發時立即使用炎爆術；對會存活較久的目標維持活體爆彈；擁有強化灼燒時，在火焰易傷少於兩層或即將消失時使用灼燒；活化烈焰冷卻結束即使用；火焰易傷五層時使用野火箭，但野火箭已疊到四層以上時絕不使用（第五層會殺死你）；霜火箭，否則火球術。移動時使用活體爆彈、活化烈焰與火焰衝擊；怪群時使用活化烈焰、活體爆彈、衝擊波、冰錐術、烈焰風暴與暴風雪。提醒：過熱時使用火焰衝擊、燃燒、冰寒脈動與急速冷卻、炎甲術或其他護甲、秘法智慧、法力寶石、寒冰護體、法力護盾、喚醒、法術反制、解除詛咒、寒冰屏障。將活體爆彈擴散到多個目標由你自行處理。"
L["rm.sod.mage.frost.Name"] = "冰霜（探索賽季）"
L["rm.sod.mage.frost.Description"] = "探索賽季的冰霜，從 10 級起，冰霜是你的主要天賦樹時選用。冰霜之指在你的結冰達到三層以上時用於冰霜長矛，否則用於極度冰凍；腦部凍結觸發時使用野火箭，其他情況在安全時使用，但野火箭已疊到四層以上時絕不使用；已紋刻時使用活體爆彈與活化烈焰；法霜箭，否則霜火箭，再否則寒冰箭。移動時使用冰霜長矛、冰霜之球、活體爆彈與火焰衝擊；怪群時使用冰霜之球、活化烈焰、活體爆彈、暴風雪與冰錐術。提醒：冰霜之球、冰寒脈動、急速冷卻、護甲、法力寶石以及其他法師提醒。在箭類法術即將命中時排入下一個法術由你自行處理。"
L["rm.sod.mage.frost.warcrafttavern.Name"] = "冰霜，火焰符文（探索賽季，Warcraft Tavern）"
L["rm.sod.mage.frost.warcrafttavern.Description"] = "Warcraft Tavern 第 4 階段使用火焰符文的冰霜配置，作為推薦的探索賽季冰霜內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。以炎爆術開場；焦炎之痕觸發時使用炎爆術；維持活體爆彈；擁有強化灼燒時以灼燒疊到五層；野火箭只在腦部凍結觸發時使用，且野火箭已疊到四層以上時絕不使用；霜火箭作為填充。移動時使用活體爆彈與火焰衝擊；怪群時使用活體爆彈、冰錐術與暴風雪。提醒：過熱時使用火焰衝擊、冰寒脈動期間使用冰霜之球、冰寒脈動、急速冷卻以及其他法師提醒。"
L["rm.sod.mage.healer.Name"] = "治療（探索賽季）"
L["rm.sod.mage.healer.Description"] = "探索賽季的法師治療，已紋刻再生或群體恢復時選用。友方目標時：生命力低於一半時使用時光倒流與時滯存護，你的時空信標不在時使用再生，群體恢復，時空異象。敵方目標時，使用能治療你信標目標的傷害技能：冰霜治療者使用法霜箭，否則飛彈彈幕觸發時使用秘法飛彈，兩層秘法衝擊時使用秘法彈幕，安全時使用野火箭（野火箭已疊到四層以上時絕不使用）以及秘法衝擊。提醒：秘法強化、氣定神閒、冰霜之球以及其他法師提醒。預設關閉：怪群時使用魔爆術，以及冰霜治療者的冰霜長矛與極度冰凍。你引導群體恢復時，下一個法術已經顯示，因此可以立刻取消它（其直接治療量很小）。要治療誰由你自行處理。"
L["rm.tbc.mage.arcane.Name"] = "秘法"
L["rm.tbc.mage.arcane.Description"] = "秘法，在秘法是你的主要天賦樹時選用。64 級前：秘法飛彈，法力不足時使用寒冰箭。64 級起：爆發期間（秘法強化、嗜血術或法力高於 35%）使用秘法衝擊，否則疊加三層秘法衝擊，然後使用寒冰箭直到層數即將消失。三個以上敵人時使用魔爆術與冰錐術。提醒包括秘法強化、氣定神閒、法力寶石與喚醒。"
L["rm.tbc.mage.fire.icyveins.Name"] = "火焰（Icy Veins）"
L["rm.tbc.mage.fire.icyveins.Description"] = "依據 Icy Veins 的火焰，在火焰是你的主要天賦樹時選用。學會炎爆術後以它開怪，強化灼燒維持五層火焰易傷，火球術作為填充，移動時使用火焰衝擊；三個以上敵人時使用衝擊波、龍之吐息與烈焰風暴。提醒：熔火護甲、魔甲術或冰甲術，目標生命力低於 20% 時使用燃燒，法力寶石、喚醒以及共用的法師輔助技能。"
L["rm.tbc.mage.fire.wowhead.Name"] = "火焰（Wowhead）"
L["rm.tbc.mage.fire.wowhead.Description"] = "依據 Wowhead 與 模擬器 的火焰。與 Icy Veins 火焰內建循環相同，但只要你站著不動，火焰衝擊一就緒就會穿插施放（傷害更高、更耗法力），並以火球術而非炎爆術開怪。這是推薦的 Icy Veins 火焰內建循環的替代選項，預設為停用：啟用它並停用那個，或提高它的優先順序。"
L["rm.tbc.mage.frost.Name"] = "冰霜"
L["rm.tbc.mage.frost.Description"] = "冰霜，適用於 1 至 70 級，也是法師在取得天賦前的預設循環。寒冰箭（4 級前為火球術），有敵人攻擊你時使用冰霜新星，與三個以上敵人交戰時使用冰錐術搭配暴風雪或魔爆術，對冰凍的目標及移動時使用冰霜長矛，法力耗盡時使用魔杖。提醒：護甲、秘法智慧、法力寶石、喚醒、法術反制、法術竊取、寒冰護體、冰寒脈動、急速冷卻與水元素。閃現術、寒冰屏障、放風箏與目標選擇由你自行處理。"
